(function(){'use strict';
/* JAH The Inorganic Chemistry Signature generator — jahdb-inorganic-chemistry-signature-1.0.
   Property of Justin Addam Higgins (JAH).
   Deterministic: same seed, same record. */
var PREFIX='JAH-INORCS-';
var FIELDS=["Foundations","Compounded","Advanced"];
var TOPICS=[{"tier": "Foundations", "g": "Fundamentals", "title": "What Is Inorganic Chemistry", "desc": "Inorganic chemistry studies all elements and their compounds except the carbon-hydrogen frameworks of organic chemistry - though the boundary is porous (organometallics, CO2, carbides live in both worlds). It spans the periodic table: main-group compounds, transition-metal complexes, clusters, and extended solids.\nIts applications are everywhere: catalysts that make fertilizers and plastics, battery materials, pigments, semiconductors, and metalloproteins. The field's questions are structural (what shape?), electronic (where are the electrons?), and mechanistic (how does it react?).", "how": "Approach any inorganic compound by locating its elements on the periodic table, assigning oxidation states, and choosing a bonding model - ionic, covalent, or delocalized. Predict geometry with VSEPR for main-group species and crystal field theory for transition-metal complexes.", "keys": ["Inorganic chemistry covers all non-organic compounds and materials.", "Spans molecules, complexes, clusters, and extended solids.", "Core questions: structure, electron distribution, mechanism.", "Underpins catalysis, batteries, pigments, semiconductors.", "Oxidation-state bookkeeping is the universal first step."], "reqs": ["Periodic-table position of each element.", "Oxidation-state assignment.", "Choice of bonding model."], "stds": ["IUPAC inorganic nomenclature (Red Book).", "Oxidation states in Roman numerals."], "cites": ["Housecroft CE, Sharpe AG. Inorganic Chemistry. 5th ed. Pearson; 2018.", "Miessler GL, Tarr DA. Inorganic Chemistry. 5th ed. Pearson; 2013."], "demo": "#!/usr/bin/env python3\n\"\"\"Assign oxidation states in simple compounds.\"\"\"\ncompounds = {\"NaCl\": {\"Na\": +1, \"Cl\": -1}, \"H2SO4\": {\"H\": +1, \"S\": +6, \"O\": -2}, \"KMnO4\": {\"K\": +1, \"Mn\": +7, \"O\": -2}}\nfor name, ox in compounds.items():\n    print(f\"  {name:6s}: \" + \", \".join(f\"{el} {v:+d}\" for el, v in ox.items()))\n"}, {"tier": "Foundations", "g": "Fundamentals", "title": "The Periodic Table Revisited: s, p, d, f Blocks", "desc": "The periodic table organizes elements by electron configuration: the s-block (groups 1-2) holds the alkali and alkaline-earth metals; the p-block (13-18) the main-group nonmetals and metalloids; the d-block (3-12) the transition metals; the f-block the lanthanides and actinides below.\nPosition predicts chemistry: s-block metals form +1/+2 ions eagerly, p-block spans the full range of oxidation states, d-block metals show variable oxidation states and colored complexes, and f-block elements are chemically similar to each other. Mendeleev's 1869 arrangement predicted undiscovered elements - the table's first triumph.", "how": "Locate an element's block from its valence configuration, then read off expected oxidation states, ionic vs covalent character, and typical coordination. Use diagonal relationships (Li/Mg, B/Si) for fine predictions. Remember the table is a map of electron filling order, not just a list.", "keys": ["Four blocks: s (1-2), p (13-18), d (3-12), f (lanthanides/actinides).", "Block determines typical oxidation states and bonding.", "Transition metals: variable states, colored complexes.", "Diagonal relationships fine-tune predictions.", "Mendeleev predicted missing elements from gaps."], "reqs": ["Electron configuration of the element.", "Group and period numbers.", "Block assignment."], "stds": ["Group numbering 1-18 (IUPAC).", "Configurations written per Aufbau with exceptions noted (Cr, Cu)."], "cites": ["Housecroft CE, Sharpe AG. Inorganic Chemistry. 5th ed. Pearson; 2018.", "Scerri E. The Periodic Table. Oxford; 2019."], "demo": "#!/usr/bin/env python3\n\"\"\"Block assignment from group number.\"\"\"\ndef block(group):\n    if group <= 2: return \"s-block\"\n    if group >= 13: return \"p-block\"\n    return \"d-block\"\nfor g in (1, 2, 8, 14, 17):\n    print(f\"  group {g:2d} -> {block(g)}\")\n"}, {"tier": "Foundations", "g": "Bonding", "title": "Ionic Bonding and Lattice Energy", "desc": "Ionic bonding is electrostatic attraction between oppositely charged ions: Na+ and Cl- pack into the rock-salt lattice, each ion surrounded by six of the opposite charge. No molecules exist in NaCl - only the extended lattice.\nLattice energy - the energy released forming the solid from gaseous ions - is estimated by the Born-Haber cycle and the Born-Lande equation: it rises with charge and falls with ion size. MgO (2+/2-) has nearly four times NaCl's lattice energy, explaining its 2852 C melting point vs 801 C.", "how": "Estimate lattice energy trends: higher charges and smaller ions mean larger lattice energy. Construct a Born-Haber cycle from sublimation, ionization, dissociation, electron affinity, and formation enthalpies to solve for the unknown step. Predict solubility trade-offs: huge lattice energies resist dissolution unless hydration energies compensate.", "keys": ["Ionic solids are extended lattices, not molecules.", "Lattice energy rises with ionic charge, falls with size.", "Born-Haber cycles dissect formation energetics.", "MgO vs NaCl shows the charge effect dramatically.", "Lattice vs hydration energy decides solubility."], "reqs": ["Ionic charges and radii.", "Born-Haber thermochemical data.", "Crystal structure type."], "stds": ["Lattice energies in kJ/mol.", "Born-Haber cycle with Hess's law."], "cites": ["Housecroft CE, Sharpe AG. Inorganic Chemistry. 5th ed. Pearson; 2018.", "Huheey JE. Inorganic Chemistry. 4th ed. HarperCollins; 1993."], "demo": "#!/usr/bin/env python3\n\"\"\"Lattice-energy trend: charge/radius proxy.\"\"\"\ndef proxy(charge, radius_pm):\n    return charge / radius_pm\nsalts = [(\"NaCl\", 1, 102+181), (\"MgO\", 2, 72+140), (\"CaF2\", 2, 100+133)]\nfor name, q, r in salts:\n    print(f\"  {name:5s}: q/r = {proxy(q, r):.4f} (higher = larger lattice energy)\")\n"}, {"tier": "Foundations", "g": "Bonding", "title": "Covalent Bonding in Inorganic Compounds", "desc": "Many inorganic compounds are covalent: SiO2, PCl5, SF6. Electronegativity differences decide character - below ~1.7 the bond is essentially covalent, above ~1.7 substantially ionic, with most real bonds between. Fajan's rules capture it: small highly charged cations polarize anions, pulling electron density into covalent sharing.\nHypervalent main-group compounds (PCl5, SF6, XeF4) exceed the octet using 3-center-4-electron bonding, not d orbitals - the modern picture. Bond polarity creates dipole moments measurable by spectroscopy and determines solubility and reactivity.", "how": "Compute electronegativity differences to estimate ionic vs covalent character. Apply Fajan's rules: covalent character rises with cation charge and falls with cation/anion size. Draw hypervalent species with 3c-4e bonds rather than expanded octets with d orbitals.", "keys": ["Electronegativity difference gauges bond character.", "Fajan's rules: small, highly charged cations polarize.", "Hypervalency uses 3-center-4-electron bonds, not d orbitals.", "Most bonds are intermediate, not purely ionic/covalent.", "Bond polarity drives solubility and reactivity."], "reqs": ["Pauling electronegativities.", "Ionic radii and charges.", "Lewis structure with octet check."], "stds": ["Electronegativity differences reported.", "3c-4e description for hypervalent species."], "cites": ["Housecroft CE, Sharpe AG. Inorganic Chemistry. 5th ed. Pearson; 2018.", "Gillespie RJ, Hargittai I. The VSEPR Model of Molecular Geometry. Dover; 2013."], "demo": "#!/usr/bin/env python3\n\"\"\"Bond character from electronegativity difference.\"\"\"\nEN = {\"Na\": 0.93, \"Cl\": 3.16, \"Si\": 1.90, \"O\": 3.44, \"C\": 2.55, \"H\": 2.20}\ndef character(a, b):\n    d = abs(EN[a]-EN[b])\n    return \"ionic\" if d > 1.7 else (\"polar covalent\" if d > 0.4 else \"nonpolar covalent\")\nfor a, b in [(\"Na\",\"Cl\"),(\"Si\",\"O\"),(\"C\",\"H\")]:\n    print(f\"  {a}-{b}: delta={abs(EN[a]-EN[b]):.2f} -> {character(a,b)}\")\n"}, {"tier": "Foundations", "g": "Bonding", "title": "VSEPR and Molecular Geometry", "desc": "Valence Shell Electron Pair Repulsion predicts shape: electron domains arrange to minimize repulsion, in the order lone pair-lone pair > lone pair-bond > bond-bond. Four domains give tetrahedral electron geometry; the molecular shape then depends on how many are lone pairs.\nWater is bent (104.5°) not linear because two lone pairs compress the H-O-H angle; ammonia is pyramidal. Five domains give trigonal bipyramidal (lone pairs equatorial), six give octahedral. VSEPR handles main-group molecules superbly and fails gracefully where d orbitals dominate.", "how": "Count steric domains (bonds + lone pairs) on the central atom. Assign electron geometry: 2 linear, 3 trigonal planar, 4 tetrahedral, 5 trigonal bipyramidal, 6 octahedral. Then name the molecular shape from atom positions only, placing lone pairs to minimize repulsion (equatorial in TBP).", "keys": ["Repulsion order: LP-LP > LP-BP > BP-BP.", "Domains set electron geometry; atoms set molecular shape.", "Lone pairs compress bond angles (H2O 104.5 deg).", "TBP: lone pairs go equatorial.", "VSEPR is a main-group model; transition metals need more."], "reqs": ["Lewis structure with lone pairs shown.", "Steric number of central atom.", "Multiple-bond domains counted once."], "stds": ["AXE notation (e.g., AX3E for ammonia).", "Bond angles in degrees."], "cites": ["Gillespie RJ, Hargittai I. The VSEPR Model of Molecular Geometry. Dover; 2013.", "Housecroft CE, Sharpe AG. Inorganic Chemistry. 5th ed. Pearson; 2018."], "demo": "#!/usr/bin/env python3\n\"\"\"VSEPR shape from AXE steric number.\"\"\"\ntable = {(2,0): \"linear\", (3,0): \"trigonal planar\", (4,0): \"tetrahedral\", (3,1): \"trigonal pyramidal\", (2,2): \"bent\", (6,0): \"octahedral\", (5,1): \"square pyramidal\"}\nfor (bonds, lp), shape in table.items():\n    print(f\"  AX{bonds}E{lp}: {shape}\")\n"}, {"tier": "Foundations", "g": "Reactivity", "title": "Oxidation States and Redox in Inorganic Chemistry", "desc": "Oxidation-state bookkeeping tracks electron flow: in MnO4- manganese is +7, in Mn2+ it is +2 - the five-electron difference is the chemistry of permanganate titrations. Rules assign states by electronegativity: oxygen -2 (except peroxides -1), hydrogen +1 with nonmetals, alkali metals +1.\nLatimer and Frost diagrams map the thermodynamics: Frost diagrams plot nE° vs oxidation state, and the lowest point is the most stable - species above the line connecting neighbors disproportionate. These diagrams predict at a glance which oxidation states survive in water.", "how": "Assign oxidation states by rule hierarchy, with the most electronegative atom taking negative states. Balance redox with half-reactions in acid (H+/H2O) or base (OH-/H2O). Read Frost diagrams: the slope between two points gives E° for the couple; a species lying above its neighbors' line disproportionates.", "keys": ["Oxidation states track electron bookkeeping.", "Frost diagrams reveal stable vs disproportionating states.", "Latimer diagrams chain reduction potentials.", "Balance redox via half-reactions (acid or base).", "High oxidation states need electronegative ligands (O, F)."], "reqs": ["Correct oxidation-state assignment.", "Acidic vs basic medium specified.", "Standard potentials for couples."], "stds": ["Half-reaction balancing with H+/H2O or OH-/H2O.", "E° values vs SHE in volts."], "cites": ["Housecroft CE, Sharpe AG. Inorganic Chemistry. 5th ed. Pearson; 2018.", "Miessler GL, Tarr DA. Inorganic Chemistry. 5th ed. Pearson; 2013."], "demo": "#!/usr/bin/env python3\n\"\"\"Frost-diagram stability check (toy data for Mn).\"\"\"\n# nE values (eV) vs oxidation state; stable if on/below hull\npts = {0: 0.0, 2: -2.36, 4: -1.08, 7: 3.57}\nstates = sorted(pts)\nfor s in states:\n    print(f\"  Mn({s:+d}): nE = {pts[s]:+.2f} eV\")\nprint(\"  lowest hull points = thermodynamically stable states\")\n"}, {"tier": "Foundations", "g": "Reactivity", "title": "Acids and Bases: The Lewis Picture", "desc": "Beyond proton transfer, Lewis defined acids as electron-pair acceptors and bases as donors: BF3 + NH3 -> F3B-NH3 is acid-base chemistry with no proton in sight. Metal cations are Lewis acids; ligands are Lewis bases - making coordination chemistry applied acid-base chemistry.\nHard-Soft Acid-Base (HSAB) theory predicts pairing: hard acids (small, highly charged: Al3+, H+) prefer hard bases (F-, O-donors); soft acids (large, polarizable: Pt2+, Hg2+) prefer soft bases (I-, S-donors, phosphines). Pearson's principle rationalizes linkage isomerism and catalyst design.", "how": "Classify reagents as hard or soft from charge density and polarizability. Predict adduct formation: hard-hard and soft-soft pairings are favored. Apply to coordination: first-row M2+/M3+ are hard-ish (O,N donors), late heavy metals are soft (P,S donors) - guiding ligand choice in synthesis.", "keys": ["Lewis acid = electron-pair acceptor; base = donor.", "Coordination chemistry is Lewis acid-base chemistry.", "HSAB: hard-hard and soft-soft pairings favored.", "Hard: small, highly charged; soft: large, polarizable.", "Guides ligand and catalyst selection."], "reqs": ["Lewis acid/base identification.", "Hard/soft classification.", "Donor atom inventory."], "stds": ["HSAB classifications per Pearson.", "Adduct formulas with donor atom specified."], "cites": ["Pearson RG. J Am Chem Soc 1963;85:3533-3539.", "Housecroft CE, Sharpe AG. Inorganic Chemistry. 5th ed. Pearson; 2018."], "demo": "#!/usr/bin/env python3\n\"\"\"HSAB pairing predictor.\"\"\"\nHARD_ACIDS = {\"Al3+\", \"H+\", \"Fe3+\"}\nSOFT_BASES = {\"I-\", \"RS-\", \"PR3\"}\ndef pairing(acid, base):\n    hard_acid = acid in HARD_ACIDS\n    soft_base = base in SOFT_BASES\n    return \"favored\" if hard_acid != soft_base else \"mismatched\"\nfor a, b in [(\"Al3+\", \"F-\"), (\"Pt2+\", \"PR3\"), (\"Al3+\", \"I-\")]:\n    print(f\"  {a} + {b}: {pairing(a, b)}\")\n"}, {"tier": "Foundations", "g": "Descriptive", "title": "Main-Group Elements: Groups 1-2", "desc": "Group 1 alkali metals (Li to Cs) are soft, low-melting, fiercely reactive: they tarnish in air, explode in water (down the group), and form +1 ions exclusively. Their compounds - NaCl, Na2CO3, Li-ion battery electrolytes - are civilization's bulk chemicals.\nGroup 2 alkaline earths (Be to Ba) are harder, higher-melting, +2 ions: Mg in chlorophyll and alloys, Ca in limestone/cement/bones, Ba in X-ray contrast. Beryllium is the exception - small, toxic, amphoteric, covalent-leaning.", "how": "Predict reactivity trends down each group: ionization energy falls, reactivity rises. Expect +1 (group 1) and +2 (group 2) ions; watch for the beryllium exception (covalent, amphoteric oxide). Flame tests identify them: Li crimson, Na yellow, K lilac, Ca brick-red, Ba green.", "keys": ["Alkali metals: +1 ions, reactivity rises down the group.", "Alkaline earths: +2 ions, harder and higher-melting.", "Beryllium is the covalent, toxic exception.", "Flame tests identify group 1-2 metals.", "Bulk chemicals: NaCl, carbonates, cement, batteries."], "reqs": ["Group assignment and period trend.", "Ionization-energy data.", "Oxide acid/base character."], "stds": ["Flame-test colors reported.", "+1/+2 oxidation states assumed unless noted."], "cites": ["Housecroft CE, Sharpe AG. Inorganic Chemistry. 5th ed. Pearson; 2018.", "Greenwood NN, Earnshaw A. Chemistry of the Elements. 2nd ed. Butterworth; 1997."], "demo": "#!/usr/bin/env python3\n\"\"\"First ionization energy trend, group 1 (kJ/mol).\"\"\"\nie = {\"Li\": 520, \"Na\": 496, \"K\": 419, \"Rb\": 403, \"Cs\": 376}\nfor el, v in ie.items():\n    print(f\"  {el:3s}: {v} kJ/mol\")\nprint(\"  trend: falls down the group -> reactivity rises\")\n"}, {"tier": "Foundations", "g": "Descriptive", "title": "Main-Group Elements: Groups 13-18", "desc": "Groups 13-18 run the full arc from metals to nonmetals: boron (metalloid, electron-deficient), carbon group (diamond to lead), pnictogens (N2 inert, P4 reactive), chalcogens (O2, sulfur rings), halogens (F2 to I2, the great oxidizers), and noble gases (inert - until Bartlett made XePtF6 in 1962).\nInert-pair effect: heavier p-block elements favor oxidation states 2 below the group number (Pb2+ over Pb4+, Bi3+). Catenation peaks at carbon and sulfur; multiple bonding fades down each group as orbitals grow diffuse.", "how": "Assign group oxidation states (group number, minus 2 for heavy elements via inert-pair effect). Expect nonmetal chemistry upper-right, metallic lower-left. Predict noble-gas reactivity: only Xe/Kr with the strongest oxidizers (PtF6, F2). Use catenation trends: C and S chain well, Si and P less so.", "keys": ["Groups 13-18 span metals to nonmetals to noble gases.", "Inert-pair effect stabilizes lower states in heavy elements.", "Halogens are strong oxidizers; noble gases nearly inert.", "Xe compounds exist (XeF2, XeF4) - Bartlett 1962.", "Catenation: C, S strong; fades down groups."], "reqs": ["Group number and period.", "Inert-pair consideration for period 6.", "Oxidizer strength for noble-gas chemistry."], "stds": ["Oxidation states with inert-pair noted.", "Noble-gas compounds cited with preparation year."], "cites": ["Greenwood NN, Earnshaw A. Chemistry of the Elements. 2nd ed. Butterworth; 1997.", "Bartlett N. Proc Chem Soc 1962:218."], "demo": "#!/usr/bin/env python3\n\"\"\"Inert-pair oxidation states for group 14.\"\"\"\ngroup14 = {\"C\": \"+4\", \"Si\": \"+4\", \"Ge\": \"+4/+2\", \"Sn\": \"+4/+2\", \"Pb\": \"+2 (inert pair wins)\"}\nfor el, ox in group14.items():\n    print(f\"  {el:3s}: {ox}\")\n"}, {"tier": "Foundations", "g": "Descriptive", "title": "The Transition Metals: Overview", "desc": "The d-block (Sc-Zn, Y-Cd, La/Hf-Hg) brings variable oxidation states, colored compounds, magnetism, and catalysis. Iron (+2/+3) carries oxygen in blood and builds civilization as steel; titanium is strong and light; copper wires the world; platinum catalyzes.\nTrends: atomic size barely shrinks across a row (poor d shielding), ionization energies rise slowly, and maximum oxidation state peaks mid-row (Mn +7, Ru/Os +8). The 4d/5d metals favor higher states and low-spin complexes; the lanthanide contraction makes 4d and 5d sizes nearly identical.", "how": "Count d electrons from oxidation state (e.g., Fe3+ = d5). Expect multiple accessible states, especially mid-row; high states need O/F ligands. Use color and magnetism as diagnostics: color implies incomplete d shell (usually), paramagnetism counts unpaired electrons.", "keys": ["Variable oxidation states are the d-block signature.", "Color and magnetism diagnose d-electron count.", "Max oxidation state peaks mid-row (Mn +7).", "4d/5d: higher states, low-spin, similar sizes (lanthanide contraction).", "Fe, Ti, Cu, Pt: the civilization metals."], "reqs": ["d-electron count from oxidation state.", "Row (3d/4d/5d) for spin-state trends.", "Ligand set for high oxidation states."], "stds": ["d^n notation with oxidation state.", "Colors reported as observed, not assumed."], "cites": ["Housecroft CE, Sharpe AG. Inorganic Chemistry. 5th ed. Pearson; 2018.", "Cotton FA, Wilkinson G. Advanced Inorganic Chemistry. 6th ed. Wiley; 1999."], "demo": "#!/usr/bin/env python3\n\"\"\"d-electron counts from oxidation states.\"\"\"\ndef d_count(element_d_electrons, ox):\n    return element_d_electrons - ox\nfor el, d, ox in [(\"Fe\", 8, 3), (\"Mn\", 7, 7), (\"Cu\", 11, 2), (\"Ti\", 4, 4)]:\n    print(f\"  {el}({ox}+): d{d_count(d, ox)}\")\n"}, {"tier": "Foundations", "g": "Coordination", "title": "Coordination Compounds: Nomenclature", "desc": "Coordination compounds pair a central metal with ligands - molecules or ions donating electron pairs: [Co(NH3)6]Cl3, K4[Fe(CN)6], cisplatin cis-[Pt(NH3)2Cl2]. Werner's 1893 theory (Nobel 1913) proposed primary valence (oxidation state) and secondary valence (coordination number) - the field's founding insight.\nNaming: ligands alphabetical (di/tri for simple, bis/tris for complex), then metal with oxidation state in Roman numerals; anionic complexes take -ate (ferrate, platinate). Coordination numbers 4 (tetrahedral or square planar) and 6 (octahedral) dominate.", "how": "Determine oxidation state from overall charge minus ligand charges. Count donor atoms for coordination number (chelates donate multiple). Name: prefix-ligands alphabetical + metal + (oxidation state); add -ate for anions. Specify geometry and isomerism (cis/trans, fac/mer) where relevant.", "keys": ["Werner: primary valence (oxidation state) + secondary (coordination number).", "Ligands named alphabetically with di/tri/bis/tris prefixes.", "Anionic complexes end in -ate.", "CN 4: tetrahedral/square planar; CN 6: octahedral.", "Chelates (EDTA, en) bind through multiple donors."], "reqs": ["Overall complex charge.", "Ligand charges and denticity.", "Geometry assignment."], "stds": ["IUPAC Red Book coordination nomenclature.", "Oxidation states in Roman numerals."], "cites": ["Werner A. Z Anorg Chem 1893;3:267-330.", "Housecroft CE, Sharpe AG. Inorganic Chemistry. 5th ed. Pearson; 2018."], "demo": "#!/usr/bin/env python3\n\"\"\"Oxidation state from complex formula data.\"\"\"\ndef ox_state(overall, ligand_charges):\n    return overall - sum(ligand_charges)\ncases = [(\"[Co(NH3)6]Cl3\", +3, [0]*6), (\"K4[Fe(CN)6]\", -4, [-1]*6)]\nfor name, chg, ligs in cases:\n    print(f\"  {name}: metal oxidation state {ox_state(chg, ligs):+d}\")\n"}, {"tier": "Compounded", "g": "Coordination", "title": "Crystal Field Theory", "desc": "Crystal field theory treats ligands as point charges splitting the metal d orbitals: in octahedral fields, the eg set (dz2, dx2-y2, pointing at ligands) rises by 3/5 Δo and the t2g set falls by 2/5 Δo. The splitting Δo decides electron configuration.\nSmall Δo (weak-field ligands, 3d metals) gives high-spin - maximum unpaired electrons. Large Δo (strong-field ligands, 4d/5d metals) gives low-spin - pairing first. This one parameter explains color, magnetism, and spectra of complexes across the d-block.", "how": "Determine Δo vs pairing energy P: Δo < P means high-spin, Δo > P low-spin. Fill t2g then eg for high-spin (Hund's rule), pair in t2g first for low-spin. Count unpaired electrons to predict magnetic moment (spin-only μ = √(n(n+2)) BM). Tetrahedral splitting Δt ≈ 4/9 Δo - always high-spin.", "keys": ["Octahedral: eg up (+3/5 Δo), t2g down (-2/5 Δo).", "High-spin vs low-spin decided by Δo vs pairing energy.", "Weak-field/3d: high-spin; strong-field/4d/5d: low-spin.", "Tetrahedral Δt ~ 4/9 Δo - always high-spin.", "Explains color, magnetism, spectra."], "reqs": ["Geometry and ligand set.", "Spectrochemical position of ligands.", "d-electron count."], "stds": ["Δo in cm⁻¹ or kJ/mol.", "Spin-only moments in Bohr magnetons."], "cites": ["Bethe H. Ann Phys 1929;3:133-208.", "Housecroft CE, Sharpe AG. Inorganic Chemistry. 5th ed. Pearson; 2018."], "demo": "#!/usr/bin/env python3\n\"\"\"Spin-only magnetic moment from unpaired electrons.\"\"\"\ndef mu(n):\n    return (n*(n+2))**0.5\nfor n in (1, 2, 3, 4, 5):\n    print(f\"  n={n} unpaired: mu = {mu(n):.2f} BM\")\n"}, {"tier": "Compounded", "g": "Coordination", "title": "Ligand Field and the Spectrochemical Series", "desc": "The spectrochemical series ranks ligands by field strength: I- < Br- < Cl- < F- < H2O < NH3 < en < CN- ≈ CO. It is largely independent of metal, letting chemists tune spin state and color by ligand choice - [Fe(H2O)6]3+ is high-spin pale violet; [Fe(CN)6]3- is low-spin deep red.\nLigand field theory adds covalency to crystal field's electrostatics: pi-donor ligands (halides, O2-) shrink Δo, pi-acceptors (CO, CN-, phosphines) enlarge it via backbonding. The nephelauxetic series ranks covalency - the cloud-expanding effect that reduces interelectron repulsion.", "how": "Place ligands on the spectrochemical series to predict Δo qualitatively. Use pi-donor/acceptor character to rationalize deviations: strong pi-acceptors stabilize low oxidation states (metal carbonyls), pi-donors stabilize high ones (oxo complexes). Combine with the metal series (3d < 4d < 5d in Δo).", "keys": ["Spectrochemical series: I- weakest ... CO strongest.", "Pi-acceptors (CO, CN-) enlarge Δo; pi-donors shrink it.", "Ligand choice tunes spin state and color.", "Metal series: Δo grows 3d < 4d < 5d.", "Nephelauxetic series ranks covalency."], "reqs": ["Ligand identities and donor atoms.", "Metal row and oxidation state.", "Observed color/magnetism for calibration."], "stds": ["Series cited in standard order.", "Δo values with units and method."], "cites": ["Tsuschida R. J Chem Soc Japan 1938;59:83.", "Housecroft CE, Sharpe AG. Inorganic Chemistry. 5th ed. Pearson; 2018."], "demo": "#!/usr/bin/env python3\n\"\"\"Spectrochemical series lookup.\"\"\"\nseries = [\"I-\", \"Br-\", \"Cl-\", \"F-\", \"H2O\", \"NH3\", \"en\", \"CN-\", \"CO\"]\nfor i, lig in enumerate(series):\n    print(f\"  {i+1}. {lig}\")\nprint(\"  field strength increases ->\")\n"}, {"tier": "Compounded", "g": "Coordination", "title": "Isomerism in Coordination Complexes", "desc": "Octahedral complexes show rich isomerism: cis/trans for MA4B2, fac/mer for MA3B3 (three identical ligands on one face vs around a meridian). Square-planar MA2B2 (cisplatin vs transplatin) shows it too - and the biology differs lethally: cisplatin is the anticancer drug, transplatin is inactive.\nOptical isomerism arises with chelates: [Co(en)3]3+ exists as non-superimposable Δ/Λ mirror images, resolved by Werner himself. Linkage isomerism (NO2- via N vs O) and ionization isomerism complete the catalog - structure determines function throughout.", "how": "Draw all geometric isomers systematically: for MA4B2 (cis/trans), MA3B3 (fac/mer). Check chirality with chelates - tris-chelate complexes are chiral (Δ/Λ). Consider linkage isomers for ambidentate ligands (SCN-, NO2-, DMSO). Confirm by spectroscopy or X-ray; dipole moments distinguish cis/trans.", "keys": ["MA4B2: cis/trans; MA3B3: fac/mer.", "cisplatin active, transplatin inactive - geometry is pharmacology.", "Tris-chelates are chiral (Δ/Λ).", "Ambidentate ligands give linkage isomers.", "Werner resolved optical isomers in 1911."], "reqs": ["Complex formula and coordination number.", "Chelate vs monodentate inventory.", "Ambidentate ligand check."], "stds": ["cis/trans, fac/mer, Δ/Λ notation.", "Isomer identity confirmed spectroscopically."], "cites": ["Werner A. Ber Dtsch Chem Ges 1911;44:1887-1898.", "Rosenberg B. Nature 1965;205:698-699."], "demo": "#!/usr/bin/env python3\n\"\"\"Count geometric isomers for octahedral types.\"\"\"\ntable = {\"MA5B\": 1, \"MA4B2\": 2, \"MA3B3\": 2, \"MA2B2C2\": 5}\nfor f, n in table.items():\n    print(f\"  {f}: {n} geometric isomer(s)\")\n"}, {"tier": "Compounded", "g": "Coordination", "title": "Substitution Reactions in Complexes", "desc": "Ligand substitution replaces one ligand with another: [Co(NH3)5Cl]2+ + H2O -> [Co(NH3)5(H2O)]3+ + Cl-. Mechanisms mirror organic substitution - D (dissociative), A (associative), I (interchange) - diagnosed by rate laws and activation volumes.\nLability trends: 3d high-spin complexes are labile (fast), low-spin d6 (Co3+, Pt2+ square planar) are inert (slow) - crystal field activation energy explains it. The trans effect in Pt(II) directs substitution: ligands trans to strong trans-directors (CO, C2H4, PR3) leave faster - the basis of cisplatin synthesis.", "how": "Measure kinetics: first-order in complex only suggests D; dependence on entering ligand suggests A. Predict lability from d-count and spin state (d3, low-spin d6 inert). Exploit the trans effect in Pt(II) synthesis: choose the order of addition so the desired isomer forms - strong trans-director installed last ends up trans to the weakest.", "keys": ["D/A/I mechanisms diagnosed by rate laws.", "Low-spin d6 and Pt(II): inert; high-spin 3d: labile.", "Trans effect orders Pt(II) substitution.", "CFAE rationalizes lability trends.", "Cisplatin synthesis exploits the trans effect."], "reqs": ["Rate law and activation parameters.", "d-count, spin state, geometry.", "Trans-director ranking for Pt(II)."], "stds": ["D/A/I labels with evidence cited.", "Rate constants with units and temperature."], "cites": ["Basolo F, Pearson RG. Mechanisms of Inorganic Reactions. 2nd ed. Wiley; 1967.", "Housecroft CE, Sharpe AG. Inorganic Chemistry. 5th ed. Pearson; 2018."], "demo": "#!/usr/bin/env python3\n\"\"\"Trans-effect series for Pt(II).\"\"\"\nseries = [\"H2O\", \"NH3\", \"Cl-\", \"Br-\", \"I-\", \"PR3\", \"CO\", \"C2H4\"]\nfor i, lig in enumerate(series):\n    print(f\"  {i+1}. {lig}\")\nprint(\"  trans-directing ability increases ->\")\n"}, {"tier": "Compounded", "g": "Organometallic", "title": "Organometallic Chemistry Basics", "desc": "Organometallics pair metals with carbon ligands: Zeise's salt K[PtCl3(C2H4)] (1827) was first; ferrocene Fe(C5H5)2 (1951) ignited the modern field with its sandwich structure. Bonding spans sigma alkyls, pi-bound alkenes/alkynes, allyls, and aromatic rings.\nThe Dewar-Chatt-Duncanson model describes alkene binding: sigma donation from pi to metal plus pi backdonation from metal to pi* - synergic bonding that activates the ligand. Hapticity (η) counts bound atoms: η2-ethylene, η5-cyclopentadienyl, η6-benzene.", "how": "Assign hapticity by counting contiguous bound atoms. Apply the Dewar-Chatt-Duncanson picture: donation and backdonation together. Check the 18-electron rule as a stability guide. Expect activated ligands - coordinated alkenes undergo nucleophilic attack (Wacker process).", "keys": ["Metal-carbon bonds: the organometallic definition.", "Ferrocene (1951) launched the modern field.", "Dewar-Chatt-Duncanson: donation + backdonation.", "Hapticity η counts bound atoms.", "Coordination activates ligands toward reaction."], "reqs": ["Ligand hapticity assignment.", "Electron count (18-e check).", "Oxidation state of metal."], "stds": ["η notation with superscript numbers.", "Electron counting per covalent or ionic method (stated)."], "cites": ["Kealy TJ, Pauson PL. Nature 1951;168:1039-1040.", "Elschenbroich C. Organometallics. 3rd ed. Wiley-VCH; 2006."], "demo": "#!/usr/bin/env python3\n\"\"\"Hapticity electron contributions (ionic method).\"\"\"\nligands = {\"η1-alkyl\": 2, \"η2-alkene\": 2, \"η3-allyl\": 4, \"η5-Cp\": 6, \"η6-benzene\": 6, \"CO\": 2}\nfor name, e in ligands.items():\n    print(f\"  {name:12s}: {e} e-\")\n"}, {"tier": "Compounded", "g": "Organometallic", "title": "The 18-Electron Rule", "desc": "Stable organometallics usually total 18 valence electrons - the noble-gas configuration: Cr(CO)6 (6 + 6×2), Fe(CO)5, Ni(CO)4. It is a guide, not a law: 16-electron square-planar d8 complexes (Pt(II), Rh(I)) are stable, and early metals often fall short.\nCounting methods: covalent (neutral ligands, metal valence electrons) or ionic (ligands as anions). Both give the same total when applied consistently. The rule predicts reactivity - 16-electron species add ligands; 18-electron species must lose one first (dissociative substitution).", "how": "Count: metal valence electrons + 2 per 2-electron donor (adjust for X-type ligands by method). Check 18 (or 16 for square-planar d8). Predict: <18 may associate, 18 must dissociate before reacting. Use violations diagnostically - stable 16-e complexes signal square-planar d8 geometry.", "keys": ["18 valence electrons ≈ noble-gas stability.", "Cr(CO)6, Fe(CO)5, Ni(CO)4 are textbook examples.", "16-e stable for square-planar d8.", "Counting: covalent or ionic method, applied consistently.", "Electron count predicts associative vs dissociative reactivity."], "reqs": ["Ligand donor-type classification.", "Counting method stated.", "Geometry for 16-e exceptions."], "stds": ["Electron counts with method named.", "18-e/16-e rationale for observed reactivity."], "cites": ["Tolman CA. Chem Soc Rev 1972;1:337-353.", "Elschenbroich C. Organometallics. 3rd ed. Wiley-VCH; 2006."], "demo": "#!/usr/bin/env python3\n\"\"\"18-electron counts (covalent method).\"\"\"\ndef count(metal_e, donors):\n    return metal_e + 2*donors\nfor name, me, d in [(\"Cr(CO)6\", 6, 6), (\"Ni(CO)4\", 10, 4), (\"Fe(CO)5\", 8, 5)]:\n    print(f\"  {name:9s}: {count(me, d)} e-\")\n"}, {"tier": "Compounded", "g": "Organometallic", "title": "Catalysis by Transition Metals", "desc": "Homogeneous catalysts - Wilkinson's RhCl(PPh3)3 for hydrogenation, Ziegler-Natta Ti/Al for polymerization, Grubbs Ru for olefin metathesis (Nobel 2005) - run the great industrial reactions. Each cycle turns over thousands of times: oxidative addition, insertion, beta-hydride elimination, reductive elimination.\nHeterogeneous catalysts (Fe for Haber-Bosch ammonia, Pt/Rh for catalytic converters, zeolites for cracking) dominate bulk chemicals. The elementary steps are the same vocabulary in both worlds; the difference is phase, separation, and site definition.", "how": "Write the catalytic cycle with elementary steps, checking electron counts and oxidation states at each. Identify the turnover-limiting step from kinetics. For asymmetric catalysis (Noyori, Knowles, Sharpless - Nobel 2001), use chiral ligands to bias diastereomeric transition states.", "keys": ["Elementary steps: OA, insertion, β-H elimination, RE.", "Wilkinson, Ziegler-Natta, Grubbs: landmark catalysts.", "Haber-Bosch Fe: the catalyst feeding half the world.", "Chiral ligands enable asymmetric catalysis.", "Turnover number measures catalyst productivity."], "reqs": ["Full catalytic cycle with balanced steps.", "Oxidation states at each intermediate.", "Turnover number/frequency data."], "stds": ["TON/TOF reported with conditions.", "Enantiomeric excess for asymmetric reactions."], "cites": ["Grubbs RH. Handbook of Metathesis. Wiley-VCH; 2003.", "Ertl G. Angew Chem 2008;47:3524-3535."], "demo": "#!/usr/bin/env python3\n\"\"\"Turnover number from product and catalyst amounts.\"\"\"\ndef ton(mol_product, mol_cat):\n    return mol_product / mol_cat\nprint(f\"  10 mol product / 0.001 mol cat: TON = {ton(10, 0.001):.0f}\")\n"}, {"tier": "Compounded", "g": "Bioinorganic", "title": "Bioinorganic Chemistry: Metalloproteins", "desc": "Life runs on metals: hemoglobin/myoglobin (Fe) carry O2, cytochromes (Fe) move electrons, carbonic anhydrase (Zn) hydrates CO2 at 10^6 turnovers/second, nitrogenase (FeMo) fixes N2, photosystem II (Mn4Ca) oxidizes water. The protein tunes the metal - same iron, wildly different jobs.\nO2 binding in hemoglobin is cooperative: the first O2 makes the next three easier (sigmoidal curve), with the Bohr effect (H+/CO2) unloading O2 in tissues. Coordination chemistry explains biology: ligand field, redox potentials, and Lewis acidity in protein scaffolds.", "how": "Identify the metal, its oxidation/spin state, and donor set from spectroscopy. Relate function to coordination: O2 carriers need reversible binding (Fe2+, protected from oxidation); redox enzymes tune potentials with ligand sets. Model active sites with small-molecule mimics to test mechanistic hypotheses.", "keys": ["Fe: O2 transport and electron transfer; Zn: Lewis-acid catalysis.", "Nitrogenase (FeMo) fixes N2; PSII (Mn4Ca) splits water.", "Hemoglobin cooperativity gives sigmoidal O2 binding.", "Protein environment tunes metal reactivity.", "Model complexes test mechanistic proposals."], "reqs": ["Metal identity and oxidation state.", "Donor-atom set from structure/spectroscopy.", "Functional assay (binding, turnover)."], "stds": ["Metal oxidation/spin states specified.", "O2-binding curves with P50 values."], "cites": ["Lippard SJ, Berg JM. Principles of Bioinorganic Chemistry. University Science; 1994.", "Bertini I. Biological Inorganic Chemistry. University Science; 2007."], "demo": "#!/usr/bin/env python3\n\"\"\"Hill equation for cooperative O2 binding (n=2.8).\"\"\"\ndef saturation(p, p50=26, n=2.8):\n    return p**n / (p50**n + p**n)\nfor p in (20, 40, 100):\n    print(f\"  pO2 {p:3d} torr: saturation {saturation(p):.2f}\")\n"}, {"tier": "Compounded", "g": "Solids", "title": "Solid-State Structures: Unit Cells and Packing", "desc": "Crystals are repeating unit cells: cubic (simple, bcc, fcc), with atoms at corners, faces, centers. Close packing (hcp, ccp) fills 74% of space; bcc 68%, simple cubic 52%. Ionic structures derive from packed anions with cations in holes: NaCl (octahedral holes), ZnS (tetrahedral), CsCl (cubic).\nRadius-ratio rules predict coordination: r+/r- > 0.732 favors 8-coordinate (CsCl), 0.414-0.732 6-coordinate (NaCl), 0.225-0.414 4-coordinate (ZnS). Real structures distort - rules guide, data decides.", "how": "Count atoms per unit cell: corners × 1/8, faces × 1/2, body × 1. Compute packing efficiency from geometry. Apply radius-ratio rules to predict coordination, then verify against diffraction data. Derive ionic structures as anion packings with cations filling selected holes.", "keys": ["Unit cell repeats to build the crystal.", "Close packing: 74% efficiency (hcp/ccp).", "NaCl, ZnS, CsCl from hole-filling patterns.", "Radius-ratio rules predict coordination numbers.", "Count atoms: corners/8 + faces/2 + body."], "reqs": ["Unit-cell type and lattice parameters.", "Ionic radii for ratio rules.", "Diffraction confirmation."], "stds": ["Packing efficiencies as percentages.", "Structures named by prototype (NaCl-type, etc.)."], "cites": ["West AR. Solid State Chemistry. 2nd ed. Wiley; 2014.", "Housecroft CE, Sharpe AG. Inorganic Chemistry. 5th ed. Pearson; 2018."], "demo": "#!/usr/bin/env python3\n\"\"\"Atoms per unit cell.\"\"\"\ndef atoms(corners, faces, body):\n    return corners/8 + faces/2 + body\nfor name, c, f, b in [(\"simple cubic\", 8, 0, 0), (\"bcc\", 8, 0, 1), (\"fcc\", 8, 6, 0)]:\n    print(f\"  {name:13s}: {atoms(c, f, b):.0f} atoms\")\n"}, {"tier": "Compounded", "g": "Solids", "title": "Defects in Solids", "desc": "Real crystals are imperfect, and defects define properties: Schottky defects (paired vacancies, e.g., NaCl) and Frenkel defects (ion displaced to interstitial, e.g., AgCl) control ionic conductivity. Non-stoichiometry (Fe0.95O, TiO2-x) is the rule, not the exception, in transition-metal oxides.\nDoping engineers function: P in Si gives n-type (extra electrons), B gives p-type (holes) - the basis of every chip. Color centers (F-centers: electrons in anion vacancies) color alkali halides; dislocations govern metal strength and work hardening.", "how": "Write defects in Kröger-Vink notation (e.g., V_Na' for a sodium vacancy). Predict conductivity from defect mobility - Frenkel defects enable fast ion conduction (AgI batteries). Choose dopants by size and charge: aliovalent dopants create vacancies or interstitials for charge compensation.", "keys": ["Schottky: paired vacancies; Frenkel: interstitial displacement.", "Non-stoichiometry is normal in transition-metal oxides.", "Doping (P/B in Si) creates n/p-type semiconductors.", "F-centers: trapped electrons color crystals.", "Dislocations control mechanical strength."], "reqs": ["Defect type and formation energy.", "Kröger-Vink notation.", "Charge-compensation scheme for dopants."], "stds": ["Defect notation per Kröger-Vink.", "Dopant concentrations in ppm or atomic %."], "cites": ["West AR. Solid State Chemistry. 2nd ed. Wiley; 2014.", "Kittel C. Introduction to Solid State Physics. 8th ed. Wiley; 2004."], "demo": "#!/usr/bin/env python3\n\"\"\"Vacancy concentration from Boltzmann factor.\"\"\"\nimport math\ndef conc(E_eV, T):\n    k = 8.617e-5\n    return math.exp(-E_eV/(k*T))\nfor E in (0.5, 1.0, 2.0):\n    print(f\"  E={E} eV at 1000 K: {conc(E, 1000):.2e} vacancies/site\")\n"}, {"tier": "Compounded", "g": "Descriptive", "title": "Descriptive Chemistry of Nonmetals", "desc": "Hydrogen is unique: +1 with nonmetals, -1 with metals (hydrides), and H2's 436 kJ/mol bond makes it unreactive without catalyst - yet it is the fuel of stars and fuel cells. Boron is electron-deficient (B2H6 with 3c-2e bonds); silicon makes the chips and silicone polymers.\nNitrogen's N≡N triple bond (945 kJ/mol) makes N2 inert - life and industry must fix it (Haber-Bosch, nitrogenase). Phosphorus catenates (P4 tetrahedra, black phosphorus semiconductors); oxygen and sulfur show the group's range from O2 to S8 rings to SF6.", "how": "Rationalize reactivity from bond strengths: strong multiple bonds (N2, CO) mean kinetic inertness. Expect catenation from C, Si, S; electron deficiency from B, Al. Prepare hydrides from elements or by hydrolysis; handle pyrophoric ones (SiH4, P2H4) under inert atmosphere.", "keys": ["H2's strong bond needs catalysts to break.", "N2 inertness forces N-fixation chemistry.", "Boron: electron-deficient, 3c-2e bonds.", "Catenation champions: C, S, P.", "Si: semiconductors and silicones."], "reqs": ["Bond dissociation energies.", "Allotrope structures.", "Hydrolysis sensitivity."], "stds": ["Bond energies in kJ/mol.", "Allotropes named (white/red/black P, etc.)."], "cites": ["Greenwood NN, Earnshaw A. Chemistry of the Elements. 2nd ed. Butterworth; 1997.", "Housecroft CE, Sharpe AG. Inorganic Chemistry. 5th ed. Pearson; 2018."], "demo": "#!/usr/bin/env python3\n\"\"\"Bond strengths explaining inertness (kJ/mol).\"\"\"\nbonds = {\"H-H\": 436, \"N≡N\": 945, \"O=O\": 498, \"C-C\": 347}\nfor b, e in sorted(bonds.items(), key=lambda x: -x[1]):\n    print(f\"  {b:5s}: {e} kJ/mol\")\n"}, {"tier": "Compounded", "g": "Descriptive", "title": "Halogens and Noble Gases", "desc": "Halogens (F2 to I2) are the great oxidizers: fluorine (most electronegative, 3.98) fluorinates nearly everything, often violently; chlorine disinfects water; iodine is the gentle antiseptic. Interhalogens (ClF3, IF7) and polyhalides (I3-) extend the family.\nNoble gases were inert until 1962: XeF2, XeF4, XeO3, and KrF2 now exist, made with the strongest oxidizers. Helium and neon remain truly inert - their ionization energies defeat all chemistry. The 'inert gases' became the noble gases: aloof, but not untouchable.", "how": "Rank oxidizing power: F2 > Cl2 > Br2 > I2. Make interhalogens by direct combination with excess of one halogen. Prepare xenon fluorides from Xe + F2 with heat/light; handle with fluoropolymer equipment. Test oxidizing strength by displacement: Cl2 oxidizes Br- and I-, not F-.", "keys": ["Oxidizing power falls F2 > Cl2 > Br2 > I2.", "Fluorine: most electronegative element (3.98).", "XeF2, XeF4, KrF2 exist since 1962.", "He and Ne remain genuinely inert.", "Displacement reactions rank halogen oxidizers."], "reqs": ["Standard reduction potentials.", "Fluorine-handling precautions.", "Excess-reagent control for interhalogens."], "stds": ["E° values vs SHE.", "Noble-gas compounds with synthesis conditions."], "cites": ["Bartlett N. Proc Chem Soc 1962:218.", "Greenwood NN, Earnshaw A. Chemistry of the Elements. 2nd ed. Butterworth; 1997."], "demo": "#!/usr/bin/env python3\n\"\"\"Halogen displacement predictor (E° values).\"\"\"\nE = {\"F2\": 2.87, \"Cl2\": 1.36, \"Br2\": 1.07, \"I2\": 0.54}\nhals = list(E)\nfor i, h1 in enumerate(hals):\n    displaces = [h2 for h2 in hals[i+1:]]\n    print(f\"  {h1} (E={E[h1]:.2f} V) displaces: {displaces}\")\n"}, {"tier": "Advanced", "g": "Bonding", "title": "Molecular Orbital Theory for Inorganics", "desc": "MO theory builds orbitals from atomic-orbital overlap across the whole molecule: bonding, nonbonding, and antibonding levels filled by electron count. For diatomics it predicts bond order (O2: 2, with two unpaired electrons - paramagnetic, which Lewis structures miss) and magnetism.\nFor polyatomics, symmetry-adapted linear combinations (SALCs) organize ligand orbitals by irreducible representation before overlapping with metal orbitals - the rigorous route to the octahedral t2g/eg splitting that crystal field theory only approximates. Photoelectron spectroscopy tests the orbital ordering directly.", "how": "Construct the MO diagram: order atomic orbitals by energy, form SALCs of ligand orbitals by symmetry, allow same-symmetry overlap, fill with the electron count. Compute bond order = (bonding - antibonding electrons)/2. Check magnetism predictions against experiment - O2's paramagnetism is the classic test.", "keys": ["MOs span the whole molecule, not just bonds.", "Bond order = (bonding - antibonding e-)/2.", "O2 paramagnetism proves MO theory's worth.", "SALCs organize ligands by symmetry.", "Photoelectron spectra test orbital ordering."], "reqs": ["Atomic orbital energies.", "Molecular point-group symmetry.", "Total valence-electron count."], "stds": ["MO diagrams with symmetry labels.", "Bond orders to 0.5 precision."], "cites": ["Housecroft CE, Sharpe AG. Inorganic Chemistry. 5th ed. Pearson; 2018.", "Albright TA, Burdett JK, Whangbo MH. Orbital Interactions in Chemistry. 2nd ed. Wiley; 2013."], "demo": "#!/usr/bin/env python3\n\"\"\"Bond order from MO electron counts.\"\"\"\ndef bond_order(bonding, antibonding):\n    return (bonding - antibonding) / 2\nfor name, b, a in [(\"H2\", 2, 0), (\"O2\", 10, 6), (\"N2\", 10, 4), (\"F2\", 10, 8)]:\n    print(f\"  {name:3s}: bond order {bond_order(b, a):.1f}\")\n"}, {"tier": "Advanced", "g": "Solids", "title": "Band Theory of Solids", "desc": "In extended solids, atomic orbitals merge into continuous bands: the filled valence band and empty conduction band, separated by the band gap. Conductors have overlapping bands, semiconductors small gaps (Si: 1.1 eV), insulators large ones (diamond: 5.5 eV).\nBand structure in k-space (E vs crystal momentum) explains effective mass, direct vs indirect gaps (GaAs emits light; Si does not efficiently), and doping: donor levels near the conduction band (n-type), acceptor levels near valence (p-type). Every electronic device is band engineering.", "how": "Read band diagrams: gap size sets conductor/semiconductor/insulator; direct vs indirect gap decides optical efficiency. Dope deliberately - group 15 donors for n-type Si, group 13 acceptors for p-type. Measure gaps optically (absorption edge) or electrically (conductivity vs temperature).", "keys": ["Bands form from merged atomic orbitals in solids.", "Band gap decides conductor/semiconductor/insulator.", "Si 1.1 eV, diamond 5.5 eV: the range.", "Direct gaps emit light; indirect gaps do not (well).", "Doping inserts donor/acceptor levels in the gap."], "reqs": ["Crystal structure and composition.", "Measured or computed band gap.", "Dopant identity and concentration."], "stds": ["Band gaps in eV with direct/indirect noted.", "Doping in atoms/cm³."], "cites": ["Kittel C. Introduction to Solid State Physics. 8th ed. Wiley; 2004.", "West AR. Solid State Chemistry. 2nd ed. Wiley; 2014."], "demo": "#!/usr/bin/env python3\n\"\"\"Classify solids by band gap (eV).\"\"\"\ndef classify(gap):\n    if gap < 0.1: return \"conductor\"\n    if gap < 3.0: return \"semiconductor\"\n    return \"insulator\"\nfor name, gap in [(\"Cu\", 0.0), (\"Si\", 1.1), (\"GaAs\", 1.4), (\"diamond\", 5.5)]:\n    print(f\"  {name:8s} Eg={gap} eV: {classify(gap)}\")\n"}, {"tier": "Advanced", "g": "Magnetism", "title": "Magnetism: Paramagnetism to Ferromagnetism", "desc": "Magnetism starts with unpaired electrons: paramagnets are attracted to fields (Curie law χ ∝ 1/T), diamagnets weakly repelled (all paired electrons). Measuring susceptibility counts unpaired electrons - a routine characterization.\nCooperative magnetism orders spins: ferromagnets align parallel (Fe, Co, Ni - permanent magnets below the Curie temperature), antiferromagnets alternate (MnO), ferrimagnets unbalance (Fe3O4 lodestone). Exchange coupling - quantum-mechanical, not dipolar - drives ordering; superexchange works through bridging ligands.", "how": "Measure χ vs T: Curie-Weiss behavior gives the moment and Weiss constant (sign reveals ferro vs antiferro coupling). Compare spin-only moments to diagnose orbital contributions. Identify ordering temperatures (Curie/Néel) from susceptibility cusps; use neutron diffraction for magnetic structures.", "keys": ["Paramagnetism: unpaired electrons, Curie law.", "Ferromagnets align; antiferromagnets alternate; ferrimagnets unbalance.", "Exchange coupling (not dipoles) drives ordering.", "Curie/Néel temperatures mark ordering transitions.", "Susceptibility counts unpaired electrons."], "reqs": ["Susceptibility vs temperature data.", "d-electron count for spin-only comparison.", "Crystal structure for exchange pathways."], "stds": ["Moments in Bohr magnetons.", "Ordering temperatures in kelvin."], "cites": ["Kittel C. Introduction to Solid State Physics. 8th ed. Wiley; 2004.", "Housecroft CE, Sharpe AG. Inorganic Chemistry. 5th ed. Pearson; 2018."], "demo": "#!/usr/bin/env python3\n\"\"\"Curie-law susceptibility vs temperature.\"\"\"\ndef chi(C, T):\n    return C / T\nfor T in (100, 200, 300):\n    print(f\"  T={T} K: chi = {chi(1.0, T):.4f} (C=1)\")\n"}, {"tier": "Advanced", "g": "Spectroscopy", "title": "Electronic Spectra of Complexes", "desc": "d-d transitions (t2g → eg) give complexes their colors: [Ti(H2O)6]3+ absorbs yellow-green, appearing purple. They are Laporte-forbidden (g→g) - weak absorptions (ε ~ 10-100) - gaining intensity by vibronic coupling; tetrahedral complexes (no inversion center) are ~10× stronger.\nCharge-transfer bands (ligand-to-metal or metal-to-ligand) are intense (ε ~ 10^4): MnO4-'s purple is LMCT, not d-d. Tanabe-Sugano diagrams map term energies vs Δo/B, letting spectra assign Δo and Racah B (covalency measure) quantitatively.", "how": "Record UV-vis: weak bands (ε < 500) are d-d, intense ones charge transfer. Count d-d bands to assign geometry and spin state (octahedral d3: 3 bands). Fit to Tanabe-Sugano diagrams to extract Δo and B; reduced B vs free ion signals covalency (nephelauxetic effect).", "keys": ["d-d bands: weak (Laporte-forbidden), color-causing.", "Charge-transfer bands: intense (ε ~ 10^4).", "MnO4- purple is LMCT, not d-d.", "Tanabe-Sugano diagrams extract Δo and B.", "Tetrahedral d-d ~10x stronger than octahedral."], "reqs": ["UV-vis spectrum with extinction coefficients.", "d-count and geometry.", "Tanabe-Sugano diagram for the d^n case."], "stds": ["Wavenumbers in cm⁻¹, ε in M⁻¹cm⁻¹.", "Δo and B with fitting method."], "cites": ["Lever ABP. Inorganic Electronic Spectroscopy. 2nd ed. Elsevier; 1984.", "Housecroft CE, Sharpe AG. Inorganic Chemistry. 5th ed. Pearson; 2018."], "demo": "#!/usr/bin/env python3\n\"\"\"Beer-Lambert: concentration from absorbance.\"\"\"\ndef conc(A, eps, l=1.0):\n    return A / (eps * l)\nprint(f\"  A=0.50, eps=100: c = {conc(0.50, 100):.2e} M (d-d band)\")\nprint(f\"  A=0.50, eps=10000: c = {conc(0.50, 10000):.2e} M (CT band)\")\n"}, {"tier": "Advanced", "g": "Mechanisms", "title": "Reaction Mechanisms: Associative vs Dissociative", "desc": "Substitution at metals follows D (dissociative: lose ligand first), A (associative: add first), or I (interchange: concerted) paths - the inorganic analogues of SN1/SN2. Activation volume (ΔV‡) from high-pressure kinetics is decisive: positive means D, negative means A.\nOctahedral d6 low-spin complexes favor D (crowded, stable); square-planar d8 favors A (open axial sites). The Eigen-Wilkins mechanism treats solvent exchange as the model reaction, with formation constants parsed into outer-sphere association and interchange steps.", "how": "Determine the rate law: zero order in entering ligand suggests D/I_d; first order suggests A/I_a. Measure ΔV‡ under pressure for the decisive assignment. Predict from electron count and geometry: 18-electron octahedral complexes dissociate; 16-electron square-planar complexes associate.", "keys": ["D/A/I diagnosed by rate laws and ΔV‡.", "ΔV‡ positive = dissociative; negative = associative.", "Octahedral d6: D; square-planar d8: A.", "Eigen-Wilkins parses solvent-exchange kinetics.", "Electron count predicts the preferred path."], "reqs": ["Rate law with orders.", "Activation volume from pressure studies.", "Electron count and geometry."], "stds": ["ΔV‡ in cm³/mol.", "D/A/I_d/I_a labels with evidence."], "cites": ["Basolo F, Pearson RG. Mechanisms of Inorganic Reactions. 2nd ed. Wiley; 1967.", "Wilkins RG. Kinetics and Mechanism of Reactions of Transition Metal Complexes. 2nd ed. VCH; 1991."], "demo": "#!/usr/bin/env python3\n\"\"\"Mechanism assignment from activation volume.\"\"\"\ndef mechanism(dV):\n    return \"dissociative (D)\" if dV > 0 else \"associative (A)\"\nfor dV in (+12, -8, +2):\n    print(f\"  ΔV‡ = {dV:+d} cm³/mol -> {mechanism(dV)}\")\n"}, {"tier": "Advanced", "g": "Clusters", "title": "Cluster Compounds", "desc": "Clusters are molecules with direct metal-metal bonds: [Mo6Cl8]4+, [Fe4S4] cubes (ferredoxins), B12H12^2- boranes. Wade's rules relate skeletal electron pairs to geometry: closo (closed polyhedron), nido (nest, one vertex missing), arachno (web, two missing).\nBoranes are the textbook case: B5H9 (nido), B10H14 (nido), [B12H12]2- (closo icosahedron). Metal-carbonyl clusters (Rh6(CO)16) model surfaces - discrete molecules with delocalized metal-metal bonding bridging molecular and solid-state chemistry.", "how": "Count skeletal electron pairs: each BH contributes 2, each CH 3, adjust for charge. Apply Wade's rules: n+1 pairs = closo, n+2 = nido, n+3 = arachno for n vertices. For metal clusters, use the 18-electron rule per metal minus M-M bonds, or Wade-Mingos extensions.", "keys": ["Clusters have direct metal-metal (or B-B) bonds.", "Wade's rules: electron pairs dictate geometry.", "closo/nido/arachno = complete/missing-1/missing-2 vertices.", "[B12H12]2-: closo icosahedron.", "Carbonyl clusters model metal surfaces."], "reqs": ["Skeletal electron-pair count.", "Vertex count.", "Charge adjustment."], "stds": ["Wade classification stated (closo/nido/arachno).", "Electron counting method named."], "cites": ["Wade K. Adv Inorg Chem Radiochem 1976;18:1-66.", "Housecroft CE, Sharpe AG. Inorganic Chemistry. 5th ed. Pearson; 2018."], "demo": "#!/usr/bin/env python3\n\"\"\"Wade classification from skeletal electron pairs.\"\"\"\ndef wade(n_vertices, pairs):\n    return {1: \"closo\", 2: \"nido\", 3: \"arachno\"}.get(pairs - n_vertices, \"hypho\")\nfor n, p in [(12, 13), (5, 7), (10, 12)]:\n    print(f\"  {n} vertices, {p} pairs: {wade(n, p)}\")\n"}, {"tier": "Advanced", "g": "Clusters", "title": "Metal-Metal Multiple Bonds", "desc": "Cotton's 1964 Re2Cl8^2- structure revealed the quadruple bond (σ²π⁴δ²) - eclipsed chlorides held by a delta bond from d-orbital face-to-face overlap. Quadruple bonds (Mo2, W2, Re2) reach ~210 pm, far shorter than single M-M bonds.\nTriple bonds (Mo2(OR)6) and the contested quintuple bonds (Cr2, Mo2 with bulky ligands, 2005) extend the series. Bond order correlates with distance and with δ→δ* electronic transitions in the visible spectrum - theory and spectroscopy converging.", "how": "Count d electrons available for M-M bonding after ligand donation; assign σ/π/δ components by symmetry. Confirm with bond length (shorter = higher order) and δ→δ* bands in UV-vis. Use bulky ligands to stabilize the shortest bonds against oligomerization.", "keys": ["Re2Cl8^2- (1964): the first quadruple bond.", "Quadruple = σ²π⁴δ²; δ from d-orbital face overlap.", "Bond length shortens with bond order.", "Quintuple bonds reported for Cr2/Mo2 (2005).", "δ→δ* transitions fingerprint the bond."], "reqs": ["d-electron count per metal.", "M-M distance from crystallography.", "Ligand steric profile."], "stds": ["Bond orders with σ/π/δ decomposition.", "Distances in pm."], "cites": ["Cotton FA. Inorg Chem 1965;4:334-336.", "Nguyen T et al. Science 2005;310:844-847."], "demo": "#!/usr/bin/env python3\n\"\"\"M-M bond order vs distance trend (Mo2, pm).\"\"\"\ndata = [(\"single\", 1, 270), (\"triple\", 3, 222), (\"quadruple\", 4, 210)]\nfor name, order, dist in data:\n    print(f\"  {name:10s} order {order}: ~{dist} pm\")\n"}, {"tier": "Advanced", "g": "Descriptive", "title": "Lanthanides and Actinides", "desc": "The 4f lanthanides (La-Lu) are chemically near-identical: +3 ions, ionic bonding, shielded 4f orbitals giving sharp f-f absorption/emission - the basis of phosphors, lasers (Nd:YAG), and MRI contrast (Gd). The lanthanide contraction shrinks radii across the row as 4f shielding fails.\nThe 5f actinides diverge: early ones (U, Np, Pu) show multiple oxidation states (+3 to +6) and covalency; all are radioactive. Uranium (+6 as uranyl UO2^2+) fuels reactors; plutonium chemistry drove the atomic age. Separation chemistry (PUREX) exploits the small differences.", "how": "Treat lanthanides as +3, size-varying only (contraction ~15% La→Lu) - separations use ion exchange or solvent extraction on tiny size differences. Expect actinide redox variety early in the row; handle all actinides radiochemically. Assign f-f spectra with Dieke diagrams for lanthanides.", "keys": ["Lanthanides: +3, near-identical, sharp f-f spectra.", "Lanthanide contraction from poor 4f shielding.", "Nd lasers, Eu phosphors, Gd MRI contrast.", "Early actinides: variable states, some covalency.", "All actinides radioactive; U/Pu are the fuel pair."], "reqs": ["Oxidation-state assignment.", "Ionic radius for separation design.", "Radiological controls for actinides."], "stds": ["f^n configurations specified.", "Radii in pm with coordination number."], "cites": ["Cotton S. Lanthanide and Actinide Chemistry. 2nd ed. Wiley; 2013.", "Greenwood NN, Earnshaw A. Chemistry of the Elements. 2nd ed. Butterworth; 1997."], "demo": "#!/usr/bin/env python3\n\"\"\"Lanthanide contraction: ionic radii (pm, CN=6).\"\"\"\nradii = {\"La3+\": 103, \"Gd3+\": 94, \"Lu3+\": 86}\nfor ion, r in radii.items():\n    print(f\"  {ion:5s}: {r} pm\")\nprint(\"  contraction across row: ~17 pm\")\n"}, {"tier": "Advanced", "g": "Descriptive", "title": "Inorganic Rings, Chains, and Cages", "desc": "Beyond carbon chains: phosphazenes (NPCl2)3 with alternating P-N rings, borazine B3N3H6 ('inorganic benzene', isoelectronic with C6H6), siloxane chains (silicones), and S8 crowns. Polyoxometalates (Keggin [PW12O40]3-) are molecular metal-oxide clusters with catalytic and medicinal chemistry.\nCatenation rules differ: Si-Si and S-S chains are common, P-P moderate, while N-N chains are explosive (nitrogen's triple bond is too stable to share). Ring strain and pi-bonding capacity decide which inorganic rings survive.", "how": "Draw inorganic rings with correct bond orders (P=N partial double character in phosphazenes). Compare isoelectronic pairs (borazine/benzene) to isolate electronic effects. Prepare via condensation or salt metathesis; characterize by multinuclear NMR (31P, 29Si, 11B are routine).", "keys": ["Phosphazenes, borazine, siloxanes, S8: the inorganic rings.", "Borazine is isoelectronic with benzene.", "Polyoxometalates: molecular metal-oxide clusters.", "Catenation ability varies by element.", "Multinuclear NMR characterizes them."], "reqs": ["Ring/chain connectivity.", "Isoelectronic comparisons.", "Hydrolysis sensitivity (many are moisture-sensitive)."], "stds": ["Ring conformations specified.", "NMR nucleus and chemical shift reported."], "cites": ["Greenwood NN, Earnshaw A. Chemistry of the Elements. 2nd ed. Butterworth; 1997.", "Pope MT. Heteropoly and Isopoly Oxometalates. Springer; 1983."], "demo": "#!/usr/bin/env python3\n\"\"\"Ring-member inventory for inorganic rings.\"\"\"\nrings = {\"borazine\": \"B3N3\", \"cyclotriphosphazene\": \"P3N3\", \"S8\": \"S8\", \"cyclotrisiloxane\": \"Si3O3\"}\nfor name, comp in rings.items():\n    print(f\"  {name:22s}: {comp}\")\n"}, {"tier": "Advanced", "g": "Descriptive", "title": "Main-Group Organometallics", "desc": "Organolithiums (n-BuLi) and Grignards (RMgX) are the workhorse carbanions - but the main-group story is wider: organoaluminums (Ziegler-Natta co-catalysts), organoboranes (Suzuki coupling partners, hydroboration reagents), organosilicon (protecting groups, cross-coupling), organozinc (Reformatsky, Negishi), organotin (Stille coupling, PVC stabilizers).\nReactivity tracks bond polarity: C-Li and C-Mg are strongly polarized (nucleophilic/basic), C-B and C-Si less so (milder, selective), C-Sn covalent enough for radical chemistry. The right metal tunes reactivity from sledgehammer to scalpel.", "how": "Match metal to task: RLi/RMgX for strong nucleophiles (dry, inert atmosphere), R2Zn/R3B for milder additions, R4Sn for cross-coupling. Prepare by direct insertion (Mg, Zn, Li) or transmetallation. Quench protic-sensitively; titrate alkyllithiums before use (they degrade).", "keys": ["RLi/RMgX: strongest C-nucleophiles, water-intolerant.", "Organoaluminum: Ziegler-Natta co-catalysts.", "Organoboron: Suzuki coupling, hydroboration.", "Reactivity tracks C-M bond polarity.", "Choose metal to tune sledgehammer vs scalpel."], "reqs": ["Metal-carbon bond polarity estimate.", "Inert-atmosphere handling.", "Titration for alkyllithium concentration."], "stds": ["Concentrations by titration, not label.", "Coupling reactions named (Suzuki, Stille, Negishi)."], "cites": ["Elschenbroich C. Organometallics. 3rd ed. Wiley-VCH; 2006.", "Smith MB. Organic Synthesis. 4th ed. Academic Press; 2016."], "demo": "#!/usr/bin/env python3\n\"\"\"C-M bond polarity ranking (electronegativity difference).\"\"\"\nEN = {\"C\": 2.55, \"Li\": 0.98, \"Mg\": 1.31, \"B\": 2.04, \"Si\": 1.90, \"Sn\": 1.96, \"Zn\": 1.65}\nfor m in (\"Li\", \"Mg\", \"Zn\", \"B\", \"Si\", \"Sn\"):\n    print(f\"  C-{m:3s}: delta = {abs(EN[\"C\"]-EN[m]):.2f}\")\n"}, {"tier": "Advanced", "g": "Materials", "title": "Inorganic Materials: Zeolites and MOFs", "desc": "Zeolites are crystalline aluminosilicates with molecular-sized pores: ZSM-5 cracks petroleum, zeolite A softens water in detergents, and faujasite structures catalyze with shape selectivity - only molecules fitting the pores react. Their acid sites (bridging Si-OH-Al) are solid acids.\nMetal-organic frameworks (MOFs) are designer porous crystals: metal nodes + organic linkers giving record surface areas (MOF-5: ~3800 m²/g) for gas storage (H2, CO2 capture), separation, and catalysis. Reticular chemistry (Yaghi, Nobel 2025-adjacent field) builds them by design, not discovery.", "how": "Characterize porosity by N2 adsorption (BET surface area) and pore-size distribution. Match pore aperture to guest kinetic diameter for separations. Tune MOF linkers for target gases (amine groups for CO2); activate by solvent removal without framework collapse. Test zeolite acidity by NH3-TPD.", "keys": ["Zeolites: crystalline pores, shape-selective catalysis.", "ZSM-5 cracks oil; zeolite A softens water.", "MOFs: record surface areas for gas storage.", "Reticular chemistry designs frameworks deliberately.", "Pore size vs guest size decides separations."], "reqs": ["Pore aperture and surface area data.", "Framework stability (thermal/chemical).", "Guest kinetic diameters."], "stds": ["BET surface areas in m²/g.", "Pore sizes in angstroms."], "cites": ["Yaghi OM et al. Nature 2003;423:705-714.", "Cundy CS, Cox PA. Chem Rev 2003;103:663-701."], "demo": "#!/usr/bin/env python3\n\"\"\"Surface-area comparison (m²/g).\"\"\"\nmats = {\"zeolite A\": 500, \"ZSM-5\": 400, \"MOF-5\": 3800, \"activated carbon\": 1000}\nfor name, sa in sorted(mats.items(), key=lambda m: -m[1]):\n    print(f\"  {name:16s}: {sa} m²/g\")\n"}];
function buildRecord(seed,topic,sig){
  var title=topic.title+(sig?' (Signature Edition)':'');
  var desc=topic.desc;
  if(sig)desc='Signature original treatment. '+desc;
  return {
    id:(sig?'JAH-INORCS-':PREFIX)+String(seed).padStart(6,'0'),
    t:title, g:topic.g, name:title, title:title,
    description:desc,
    how_it_works:topic.how,
    key_points:topic.keys,
    requirements:topic.reqs,
    standards:topic.stds,
    citations:topic.cites,
    src:sig?'signature':'public-harvest',
    signature_label:sig?'Signature-generated original treatment - clearly labeled Signature-made and never presented as authentic public record.':'Public-harvest record - real, fact-checked domain knowledge.',
    ladder_rank:seed,
    ladder_tier:topic.tier.toLowerCase(),
    demo:{kind:'python',language:'python',program:topic.demo,
      note:'Working demonstration program for this record.'},
    _seed:seed
  };
}
function topicFor(seed,opts){
  opts=opts||{};
  var pool=TOPICS.filter(function(t){return !opts.field||t.tier===opts.field;});
  if(!pool.length)pool=TOPICS;
  var i=((seed-1)%pool.length+pool.length)%pool.length;
  return {topic:pool[i],index:TOPICS.indexOf(pool[i])};
}
function generate(seed,opts){
  var tf=topicFor(seed,opts);
  var sig=(opts&&opts.signature)||true;
  return buildRecord(tf.index+1,tf.topic,sig);
}
function validate(r){
  var e=[];
  if(!r||typeof r!=='object')return {ok:false,errors:['not an object']};
  var okId=new RegExp('^('+PREFIX.replace(/-/g,'\\-')+'|'+'JAH-INORCS-'.replace(/-/g,'\\-')+')\\d{6}$').test(r.id||'');
  if(!okId)e.push('id');
  if(FIELDS.indexOf(capTier(r.ladder_tier))<0)e.push('tier');
  if(['public-harvest','signature'].indexOf(r.src)<0)e.push('src');
  if(!r.title)e.push('title');
  if(!r.description||r.description.length<40)e.push('description');
  if(!r.demo||!r.demo.program||r.demo.program.indexOf('print')<0)e.push('demo');
  return {ok:!e.length,errors:e};
}
function capTier(s){s=String(s||'');return s.charAt(0).toUpperCase()+s.slice(1);}
function driftCheck(record,sample){
  var dups=(sample||[]).filter(function(r){return r&&r.title===record.title&&r.ladder_tier===record.ladder_tier;});
  return dups.length?{ok:false,errors:['duplicate title+tier in archive sample']}:{ok:true,errors:[]};
}
var gen={version:'jahdb-inorganic-chemistry-signature-1.0',generate:generate,validate:validate,driftCheck:driftCheck,fields:FIELDS};
if(typeof JAHDB!=='undefined'&&JAHDB.registerGenerator)JAHDB.registerGenerator('inorganic-chemistry-signature',gen);
if(typeof module!=='undefined'&&module.exports)module.exports=gen;
})();
